const mcqs = [];

function addQ(id, topic, testTag, difficulty, question, options, answer, explanation) {
    mcqs.push({
        id: `phy_${id.toString().padStart(3, '0')}`,
        subjectId: "physics",
        topic: topic,
        testTag: testTag,
        difficulty: difficulty,
        isPastPaper: true,
        question: question,
        options: options,
        answer: answer,
        explanation: explanation || `Standard ${testTag} physics question for ${topic}.`
    });
}

